//! Which block kernel each core's C driver uses, read from the `#if`
//! chain at the top of `kernel/zarch/<p>axpy.c`. Generated by
//! `tools/blas_asm/uk.zig`; re-derive it rather than editing it.

const std = @import("std");
const Block = @import("../../../uk_block.zig").Block;

pub const Entry = struct {
    role: []const u8,
    cores: []const []const u8,
    /// The driver's block size, `n & -mask`.
    mask: comptime_int,
    block: Block,
    /// The block's function, when it is assembly.
    kernel: []const u8,
    module: type,
};

pub const entries = [_]Entry{
    .{ .role = "saxpy", .cores = &.{
        "z14",
    }, .mask = 64, .block = .assembly, .kernel = "saxpy_kernel_64", .module = @import("saxpy.zig") },
    .{ .role = "daxpy", .cores = &.{
        "z13",
        "z14",
    }, .mask = 32, .block = .assembly, .kernel = "daxpy_kernel_32", .module = @import("daxpy.zig") },
    .{ .role = "caxpy", .cores = &.{
        "z14",
    }, .mask = 16, .block = .assembly, .kernel = "caxpy_kernel_16", .module = @import("caxpy.zig") },
    .{ .role = "caxpyc", .cores = &.{
        "z14",
    }, .mask = 16, .block = .assembly, .kernel = "caxpyc_kernel_16", .module = @import("caxpy.zig") },
    .{ .role = "zaxpy", .cores = &.{
        "z13",
        "z14",
    }, .mask = 8, .block = .assembly, .kernel = "zaxpy_kernel_8", .module = @import("zaxpy.zig") },
    .{ .role = "zaxpyc", .cores = &.{
        "z13",
        "z14",
    }, .mask = 8, .block = .assembly, .kernel = "zaxpyc_kernel_8", .module = @import("zaxpy.zig") },
};

/// The entry for `role` on `core`, if its driver is C.
pub fn find(comptime role: []const u8, comptime core: []const u8) ?Entry {
    @setEvalBranchQuota(1_000_000);
    inline for (entries) |e| {
        if (comptime std.mem.eql(u8, e.role, role)) {
            inline for (e.cores) |c| {
                if (comptime std.mem.eql(u8, c, core)) return e;
            }
        }
    }
    return null;
}
